components.element:
{
((
  { setValue },
  value,
  [state, setState],
  { component: Component, source, parse, ...rest }
) =>
  (() => (
    <Component
      {...rest}
      source={source}
      parse={(value) => (() => parse(value))(setState(value))}
      format={() => state}
    />
  ))(
    useEffect(() => {
      source &&
        (value
          ? value.includes(source) || setValue('parse', [...value, source])
          : setValue('parse', [source]))
    }, [setValue, value])
  ))(useFormContext(), useWatch({ name: 'parse' }), useState(''), props)
}
